import { TabContext, TabPanel } from "@mui/lab";
import {
  Box,
  Grid,
  Typography,
  Divider,
  Tooltip,
  Tabs,
  Tab,
} from "@mui/material";

import React from "react";
import { useEffect } from "react";
import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "src/hooks/useAuth";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";
import { toastError } from "src/utils/utils";

const ITSolutionDropDown = () => {
  // Import Context
  const { setResources, setOverview, setFeatures, setITSolutionId, setSlug } =
    useAuth();

  const [itSolutions, setItSolutions] = useState([]);
  const [subItSolutions, setSubItSolutions] = useState([]);
  const [subItSolutionsLists, setSubItSolutionsLists] = useState([]); // Store multiple sub-lists dynamically
  const navigate = useNavigate();
  const [activeITSolutionId, setActiveITSolutionId] = useState(null);

  const fetchITSoltionsData = () => {
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTIONS.list)
      .then((response) => {
        const responseData = response.data.data;
        setItSolutions(response.data.data);

        if (responseData.length > 0) {
          fetchSubITSoltionsData(responseData[0].id); // Get the id of the first IT solution
          setActiveITSolutionId(responseData[0].id); // Get the id of the first IT solution
        }
      })
      .catch((error) => {
        toastError(error);
      });
  };

  const fetchSubITSoltionsData = (id) => {
    axiosInstance
      .get(ApiEndpoints.SUB_IT_SOLUTIONS.list(id))
      .then((response) => {
        setSubItSolutions(response.data.data);
        const responseData = response.data.data;
        if (responseData) {
          responseData.forEach((item, index) => {
            fetchSubITSoltionsList(item.id, index);
          });
        }
      })
      .catch((error) => {
        toastError(error);
      });
  };

  const fetchSubITSoltionsList = (id, index) => {
    axiosInstance
      .get(ApiEndpoints.SUB_IT_SOLUTIONS_LIST.list(id))
      .then((response) => {
        setSubItSolutionsLists((prevState) => {
          const newState = [...prevState];
          newState[index] = response.data.data;
          return newState;
        });
      })
      .catch((error) => {
        toastError(error);
      });
  };

  useEffect(() => {
    fetchITSoltionsData();
  }, []);

  const handleITSolutionClick = (id, event) => {
    event.stopPropagation();
    fetchSubITSoltionsData(id);
    setActiveITSolutionId(id);
  };
  const generateSlug = (name) => {
    if (!name) return "default-slug"; // Provide a default value if name is undefined
    return name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-") // Replace spaces and special characters with hyphens
      .replace(/^-|-$/g, ""); // Remove leading or trailing hyphens
  };

  const fetchCommonData = async (itSolutionId) => {
    try {
      const response = await axiosInstance.get(
        ApiEndpoints.COMMON.list(itSolutionId)
      );

      // Extracting data from the API response
      const { features, overView, resources } = response.data;

      // Setting the values in the context
      setFeatures(features?.is_show || false);
      setOverview(overView?.is_show || false);
      setResources(resources?.is_show || false);

      // Return the updated values
      return {
        features: features?.is_show || false,
        overview: overView?.is_show || false,
        resources: resources?.is_show || false,
      };
    } catch (error) {
      console.error("Error fetching common data:", error);

      // Set default values in case of an error
      setFeatures(false);
      setOverview(false);
      setResources(false);

      // Return the default values
      return { features: false, overview: false, resources: false };
    }
  };

  const handleSubItSolutionClick = async (
    index,
    subITSolutionId,
    subITSolutionName
  ) => {
    if (!subITSolutionId) return;

    const { features, overview, resources } = await fetchCommonData(
      subITSolutionId
    );
    const slug = generateSlug(subITSolutionName); // Generate slug for the name
    setITSolutionId(subITSolutionId);
    setSlug(slug);
    // Conditional navigation based on data
    if (overview) {
      setOverview(true);
      navigate(`/it-solution-overview/${slug}-${subITSolutionId}`);
    } else if (features) {
      setFeatures(true);
      navigate(`/it-solution-features/${slug}-${subITSolutionId}`);
    } else if (resources) {
      setResources(true);
      navigate(`/it-solution-demo/${slug}-${subITSolutionId}`);
    } else {
      navigate(`/it-solution-demo/${slug}-${subITSolutionId}`);
    }
  };

  return (
    <>
      <Box
        sx={{
          width: "1280px",
        }}
      >
        <Grid container>
          <Grid item xs={4}>
            <Box
              sx={{
                display: "flex",
                flexDirection: "column",
                gap: 5,
                py: 5,
              }}
            >
              <Typography
                sx={{
                  fontSize: { lg: "24px" },
                  lineHeight: { lg: "32px" },
                  fontWeight: 600,
                  color: "#602DE1",
                  pl: 3,
                }}
              >
                IT Solutions
              </Typography>
              <Box
                sx={{
                  pl: 5,
                  display: "flex",
                  flexDirection: "column",
                  gap: 2,
                }}
              >
                {itSolutions?.map((item, index) => (
                  <Box
                    onClick={(event) => handleITSolutionClick(item.id, event)}
                    key={index}
                  >
                    <Typography
                      sx={{
                        fontSize: { lg: "16px" },
                        lineHeight: { lg: "24px" },
                        fontWeight: 600,
                        textWrap: "wrap",
                        "&:hover": {
                          color: "#ffff",
                          bgcolor: "#602DE1",
                        },
                        color:
                          activeITSolutionId === item.id ? "#ffff" : "#101828",
                        bgcolor:
                          activeITSolutionId === item.id ? "#602DE1" : "",
                        borderRadius: "10px",
                        cursor: "pointer",
                        px: 2,
                        py: 2,
                      }}
                    >
                      {item.title}
                    </Typography>
                  </Box>
                ))}
              </Box>
            </Box>
          </Grid>
          <Grid
            item
            xs={8}
            columnSpacing={10}
            sx={{
              px: 10,
              py: 5,
              display: "flex",
              flexWrap: "wrap",
              alignItems: "flex-start",
              gap: 6,
            }}
          >
            {subItSolutions?.map((item, index) => (
              <Box
                key={index}
                sx={{
                  width: "30%",
                }}
              >
                <Box sx={{ mb: 3 }}>
                  <Typography
                    sx={{
                      fontSize: { lg: "16px" },
                      lineHeight: { lg: "24px" },
                      fontWeight: 600,
                      color: "#602DE1",
                      mb: 1,
                      wordBreak: "break-word",
                      whiteSpace: "break-spaces",
                    }}
                  >
                    {item.title}
                  </Typography>

                  <Typography
                    sx={{
                      fontSize: { lg: "14px" },
                      lineHeight: { lg: "20px" },
                      fontWeight: 400,
                      color: "#667085",
                      mb: 2,
                    }}
                  >
                    <div
                      style={{
                        textWrap: "wrap",
                        whiteSpace: "break-spaces",
                      }}
                      dangerouslySetInnerHTML={{
                        __html: `<style>p { margin: 0; }</style>${item.description}`,
                      }}
                    />
                  </Typography>
                </Box>
                <Box
                //  sx={{ mb: 5 }}
                >
                  <Divider sx={{ width: "50%", borderWidth: "1px" }} />
                </Box>
                {subItSolutionsLists[index]?.map((subItem, subIndex) => (
                  <Box
                    key={subIndex}
                    onClick={() =>
                      handleSubItSolutionClick(
                        subIndex,
                        subItem.id,
                        subItem?.title
                      )
                    }
                    sx={{ mb: 10 }}
                  >
                    <Typography
                      sx={{
                        fontSize: { lg: "16px" },
                        lineHeight: { lg: "24px" },
                        fontWeight: 500,
                        color: "#101828",
                        textWrap: "wrap",
                        "&:hover": {
                          color: "#602DE1",
                          cursor: "pointer",
                        },
                        mb: 1,
                      }}
                    >
                      {subItem.title}
                    </Typography>
                    <Typography
                      sx={{
                        fontSize: { lg: "14px" },
                        lineHeight: { lg: "20px" },
                        fontWeight: 400,
                        color: "#667085",
                      }}
                    >
                      <div
                        style={{ textWrap: "wrap", whiteSpace: "break-spaces" }}
                        dangerouslySetInnerHTML={{
                          __html: `<style>p { margin: 0; }</style>${subItem.description}`,
                        }}
                      />
                    </Typography>
                  </Box>
                ))}
              </Box>
            ))}
          </Grid>
        </Grid>
      </Box>
    </>
  );
};

export default ITSolutionDropDown;
